import{V as e,ht as t,nt as n,tt as r}from"./chunks/framework.wxcks8ca.js";var i=JSON.parse(`{"title":"交互与输入","description":"","frontmatter":{},"headers":[],"relativePath":"kimi-code-cli/guides/interaction.md","filePath":"zh/kimi-code-cli/guides/interaction.md"}`),a={name:`kimi-code-cli/guides/interaction.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="交互与输入" tabindex="-1">交互与输入 <a class="header-anchor" href="#交互与输入" aria-label="Permalink to “交互与输入”">​</a></h1><p>Kimi Code CLI 以交互式 TUI 运行，核心由输入框、对话视图和状态栏三部分组成。本页介绍输入方式、媒体粘贴、审批流程和模式切换。</p><h2 id="输入框基本操作" tabindex="-1">输入框基本操作 <a class="header-anchor" href="#输入框基本操作" aria-label="Permalink to “输入框基本操作”">​</a></h2><p>输入框接受自由文本：<code>Enter</code> 发送，<code>Shift-Enter</code> 或 <code>Ctrl-J</code> 插入换行。输入框为空时按 <code>↑</code> / <code>↓</code> 浏览当前工作目录的历史输入，包括此前运行过的 Shell 命令。</p><p><strong>退出 CLI</strong>：输入框为空时按 <code>Ctrl-D</code>，或空闲状态下连按 <code>Ctrl-C</code> 两次，或输入 <code>/exit</code>。流式输出期间按 <code>Ctrl-C</code> 或 <code>Esc</code> 是中断当前轮次，不会退出程序。</p><h2 id="粘贴图片与视频" tabindex="-1">粘贴图片与视频 <a class="header-anchor" href="#粘贴图片与视频" aria-label="Permalink to “粘贴图片与视频”">​</a></h2><p>Kimi Code CLI 支持在输入框中直接粘贴图片和视频，让 AI 结合视觉内容理解你的问题——截图报错、UI 设计图、架构图，直接粘贴进去就能讨论，无需上传或转存。</p><p><strong>视频输入是 Kimi Code 的特色能力</strong>，支持直接粘贴视频片段让模型分析其中的内容、界面流程或代码演示。</p><p>操作方式：</p><ul><li><strong>macOS / Linux</strong>：<code>Ctrl-V</code></li><li><strong>Windows</strong>：<code>Alt-V</code></li></ul><p>粘贴后输入框显示占位符，可像普通文本一样编辑；提交时自动替换为实际内容。纯文本剪贴板会回退到普通粘贴。媒体功能是否可用取决于当前模型的多模态能力（<code>image_in</code> / <code>video_in</code>），登录 Kimi Code 账号后默认开启。</p><h2 id="斜杠命令" tabindex="-1">斜杠命令 <a class="header-anchor" href="#斜杠命令" aria-label="Permalink to “斜杠命令”">​</a></h2><p>以 <code>/</code> 开头的内容会被识别为斜杠命令。输入 <code>/</code> 后弹出补全菜单，随后续字符实时过滤；按 <code>Esc</code> 关闭菜单，匹配失败时内容会作为普通消息发送给 Agent。</p><p>已激活的 <a href="/code/docs/kimi-code-cli/customization/skills.html">Agent Skills</a> 会自动注册为斜杠命令：普通外部 Skill 以 <code>/skill:&lt;name&gt;</code> 调用，外部子 Skill 以 <code>/parent.child</code> 这样的点分命令显示，内置 Skill 直接以 <code>/&lt;name&gt;</code> 出现在斜杠命令面板中；若外部 Skill 名称与系统斜杠命令不冲突，也可以省略 <code>skill:</code> 前缀直接输入 <code>/&lt;name&gt;</code>。</p><p>部分命令仅在 Agent 空闲时可用，流式输出或上下文压缩期间需先按 <code>Esc</code> 中断。<code>/yolo</code>、<code>/plan</code>、<code>/help</code>、<code>/btw</code> 等模式切换和查询类命令则始终可用。全部命令说明见<a href="/code/docs/kimi-code-cli/reference/slash-commands.html">斜杠命令参考</a>。</p><h2 id="文件引用" tabindex="-1">文件引用 <a class="header-anchor" href="#文件引用" aria-label="Permalink to “文件引用”">​</a></h2><p>键入 <code>@</code> 触发文件路径补全，选中后在输入中插入相对路径，Agent 读取时会直接加载该文件内容。文件引用在 git 和非 git 目录都可用；文件夹候选会以 <code>/</code> 结尾，方便继续补全其下路径。如果快速搜索辅助工具仍在下载，Kimi Code 会先回退到基础的文件系统扫描。隐藏路径也可补全，但 <code>.git</code> 会从候选中排除。</p><blockquote><p><code>@</code> 引用和斜杠命令是两套不同的机制：<code>@</code> 向 Agent 提供文件上下文，<code>/</code> 调用内置功能或 Skill。前面有空白字符时输入 <code>/</code> 会按普通文本处理，不会打开斜杠命令菜单。</p></blockquote><h2 id="审批流程" tabindex="-1">审批流程 <a class="header-anchor" href="#审批流程" aria-label="Permalink to “审批流程”">​</a></h2><p>Agent 调用会产生副作用的工具（修改文件、执行命令等）时，TUI 会弹出审批面板让你确认。YOLO 模式下的普通工具调用，以及 Plan 模式下对计划文件的写入，不触发审批。</p><p>用方向键选择选项，<code>Enter</code> 确认；也可以按 <code>1</code>/<code>2</code>/<code>3</code> 数字键直接选择。<code>Esc</code>、<code>Ctrl-C</code>、<code>Ctrl-D</code> 等同于拒绝。</p><p>面板中通常有「Approve for this session」选项，选择后本次会话内的同类调用将自动放行。如需永久规则，在<a href="/code/docs/kimi-code-cli/configuration/config-files.html#permission">配置文件</a>里预置 allow / deny 规则即可。</p><h2 id="模式切换" tabindex="-1">模式切换 <a class="header-anchor" href="#模式切换" aria-label="Permalink to “模式切换”">​</a></h2><h3 id="plan-模式" tabindex="-1">Plan 模式 <a class="header-anchor" href="#plan-模式" aria-label="Permalink to “Plan 模式”">​</a></h3><p>Plan 模式下，Agent 先输出行动计划，等待你确认后才动手修改文件，适合复杂或高风险任务。</p><ul><li>切换：<code>Shift-Tab</code> 或 <code>/plan</code></li><li>清除当前计划：<code>/plan clear</code>（仅空闲时）</li></ul><p>Agent 输出方案后会等待你审批——可批准执行、拒绝、或要求修改。退出 Plan 模式需要你确认，即使开启了 YOLO 模式也不例外。Auto 模式例外：计划退出会自动批准，并在记录中标记为 &quot;Auto-approved&quot;。</p><h3 id="yolo-auto-模式" tabindex="-1">YOLO / Auto 模式 <a class="header-anchor" href="#yolo-auto-模式" aria-label="Permalink to “YOLO / Auto 模式”">​</a></h3><p><strong>YOLO 模式</strong>（<code>/yolo</code>）自动批准普通工具调用，适合已知安全的批处理任务。敏感操作仍会询问——例如访问 <code>.env</code>、SSH 私钥等敏感文件，或退出 Plan 模式——Agent 也仍可能向你提问。</p><p><strong>Auto 模式</strong>（<code>/auto</code>）是完全无人值守模式：所有工具审批自动处理，包括敏感文件和计划退出，且 Agent 不会向你提问，完全由它自己做决定。</p><div class="warning custom-block"><p class="custom-block-title">注意</p><p>YOLO 模式会跳过文件写入和命令执行的确认，请只在受信任的工作目录下使用。</p></div><h3 id="shell-模式" tabindex="-1">Shell 模式 <a class="header-anchor" href="#shell-模式" aria-label="Permalink to “Shell 模式”">​</a></h3><p>Shell 模式让你不离开对话就能运行终端命令，命令输出会写入对话上下文，AI 在后续轮次能够看到这些结果。</p><ul><li>进入：在空输入框中键入 <code>!</code>，或粘贴以 <code>!</code> 开头的命令。</li><li>退出：在空输入框中按 <code>Backspace</code> 或 <code>Esc</code>；提交命令后也会自动回到普通模式。</li><li>后台运行：命令执行期间按 <code>Ctrl+B</code> 可将其转为后台任务。</li><li>召回历史命令：在 Shell 模式的空输入框中按 <code>↑</code> 浏览此前运行过的 Shell 命令，召回后仍处于 Shell 模式，可再次作为命令执行。</li></ul><p>进入 Shell 模式后，输入框左侧会显示 <code>!</code> 提示符，边框变为紫色。例如，无需新开终端就能运行 <code>!gh auth login</code> 登录 GitHub CLI，登录后 Kimi 就可以直接使用 <code>gh</code>。</p><h2 id="流式输出期间" tabindex="-1">流式输出期间 <a class="header-anchor" href="#流式输出期间" aria-label="Permalink to “流式输出期间”">​</a></h2><p>Agent 思考或调用工具时，输入框仍然可用，支持以下额外操作：</p><ul><li><strong><code>Ctrl-S</code></strong>：把输入框中的内容立即注入正在运行的轮次，无需等待结束</li><li><strong><code>Esc</code> / <code>Ctrl-C</code></strong>：中断当前轮次</li><li><strong><code>Ctrl-O</code></strong>：全局切换工具输出和压缩摘要的折叠状态</li></ul><h2 id="外部编辑器" tabindex="-1">外部编辑器 <a class="header-anchor" href="#外部编辑器" aria-label="Permalink to “外部编辑器”">​</a></h2><p>按 <code>Ctrl-G</code> 把当前输入内容发给外部编辑器，保存后回填到输入框，不保存则保持原样。适合需要输入大段文本或带格式内容的场景。</p><p>编辑器优先级：<code>/editor</code> 配置 &gt; <code>$VISUAL</code> 环境变量 &gt; <code>$EDITOR</code> 环境变量。未配置时可先运行 <code>/editor</code> 选择默认编辑器。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="/code/docs/kimi-code-cli/reference/keyboard.html">键盘快捷键</a> — 全部快捷键的完整速查表</li><li><a href="/code/docs/kimi-code-cli/reference/slash-commands.html">斜杠命令</a> — 所有内置命令的说明与别名</li><li><a href="/code/docs/kimi-code-cli/guides/sessions.html">会话与上下文</a> — 如何恢复会话、压缩上下文、导出对话</li></ul>`,43)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};